#include <iostream>
#include <string>

using namespace std;

bool isSimilar(string A, string B) {
    int m = A.size(), n = B.size();
    if (abs(m - n) > 1) return false;

    if (m == n) {
        int diff = 0;
        for (int i = 0; i < m; ++i) {
            if (A[i] != B[i]) {
                  if (++diff > 1) return false;
              }
        }
        return diff <= 1;
    } else {
        string& shorter = (m < n) ? A : B;
        string& longer = (m < n) ? B : A;

        int i = 0, j = 0;
        int diff = 0;
        while (i < shorter.size() && j < longer.size()) {
              if (shorter[i] != longer[j]) {
                  if (++diff > 1) return false;
                  ++j;
              } else {
                  ++i;
                  ++j;
              }
        }
        return true;
    }
}

int main() {
    int T;
    cin >> T;

    while (T--) {
        string A, B;
        cin >> A >> B;
        if (isSimilar(A, B)) {
            cout << "similar" << endl;
        } else {
            cout << "not similar" << endl;
        }
    }

    return 0;
}

