#include <cstdlib>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

static bool similar(const string& A, const string& B) {
    int m = A.size(), n = B.size();
    if (abs(m - n) > 1) return false;
    if (m > n) return similar(B, A);
    if (m == n) {
        int diff = 0;
        for (int i = 0; i < m; ++i) if (A[i] != B[i] && ++diff > 1) return false;
        return true;
    }
    int i = 0, j = 0, skip = 0;
    while (j < n) {
        if (i < m && A[i] == B[j]) { ++i; ++j; }
        else if (++skip > 1) return false;
        else ++j;
    }
    return true;
}
static bool check(const string& exe, const vector<pair<string, string>>& pairs, int id) {
    const string inF = "l4a03p1_in.txt", outF = "l4a03p1_out.txt";
    {
        ofstream o(inF);
        o << pairs.size() << '\n';
        for (size_t i = 0; i < pairs.size(); ++i) o << pairs[i].first << ' ' << pairs[i].second << '\n';
    }
    int code = system(("\"" + exe + "\" < " + inF + " > " + outF + " 2>/dev/null").c_str());
    vector<string> gotLines, wantLines;
    {
        ifstream in(outF);
        string line;
        while (getline(in, line)) {
            if (!line.empty() && line.back() == '\r') line.pop_back();
            gotLines.push_back(line);
        }
    }
    for (size_t i = 0; i < pairs.size(); ++i)
        wantLines.push_back(similar(pairs[i].first, pairs[i].second) ? "similar" : "not similar");
    if (code != 0 || gotLines.size() != wantLines.size() || gotLines != wantLines) {
        cout << "[FAIL] case " << id << ": expected " << wantLines.size() << " lines, actual "
             << gotLines.size() << " lines, status=" << code << '\n';
        return false;
    }
    return true;
}
int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    const string exe = argv[1];
    int passed = 0, total = 0;
    vector<pair<string, string>> c1;
    c1.push_back(make_pair("apple", "applee"));
    c1.push_back(make_pair("apple", "appe"));
    c1.push_back(make_pair("apple", "bpple"));
    c1.push_back(make_pair("applee", "bpple"));
    c1.push_back(make_pair("apple", "apple"));
    ++total; if (check(exe, c1, 1)) ++passed;  // 样例1
    vector<pair<string, string>> c2;
    c2.push_back(make_pair("a", "b"));
    c2.push_back(make_pair("ab", "cd"));
    c2.push_back(make_pair("abc", "acb"));
    c2.push_back(make_pair("ab", "ba"));
    c2.push_back(make_pair("abc", "abcd"));
    c2.push_back(make_pair("xyz", "xy"));
    c2.push_back(make_pair("a", "aa"));
    c2.push_back(make_pair("aaaa", "aaab"));
    c2.push_back(make_pair("abcdef", "abcxyz"));
    c2.push_back(make_pair("abcdefghijkl", "abcxdefghi"));
    string longSame(50, 'a'), longOne = longSame, longTwo = longSame;
    longOne[24] = 'b';
    longTwo[10] = 'c'; longTwo[30] = 'd';
    c2.push_back(make_pair(longSame, longSame));
    c2.push_back(make_pair(longSame, longOne));
    c2.push_back(make_pair(longSame, longTwo));
    ++total; if (check(exe, c2, 2)) ++passed;  // 边界
    srand(20240301);
    for (int t = 0; t < 4; ++t) {
        vector<pair<string, string>> c;
        int T = 1 + rand() % 40;
        for (int i = 0; i < T; ++i) {
            string A, B;
            int la = 1 + rand() % 50, lb = la + (rand() % 3 - 1);
            if (lb < 1) lb = 1;
            for (int k = 0; k < la; ++k) A += char('a' + rand() % 26);
            for (int k = 0; k < lb; ++k) B += char('a' + rand() % 26);
            int r = rand() % 10;
            if (r == 0 && la == lb && la > 0) B[(rand() % la)] = A[(rand() % la)];
            else if (r == 1 && la == lb && la > 0) B[(rand() % la)] = char('a' + ((B[(rand() % la)] - 'a' + 1) % 26));
            else if (r == 2) B = A.substr(0, la > 1 ? la - 1 : 1);
            c.push_back(make_pair(A, B));
        }
        ++total; if (check(exe, c, 3 + t)) ++passed;
    }
    cout << "Results: " << passed << "/" << total << " passed" << '\n';
    return passed == total ? 0 : 1;
}

