#include <algorithm>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

static int greedy(const vector<long long>& a) {
    vector<long long> b = a;
    sort(b.begin(), b.end());
    int k = 0;
    for (size_t i = 0; i < b.size(); ++i) {
        if (b[i] >= (long long)(k + 1)) ++k;
    }
    return k;
}
static int brute(const vector<long long>& a) {
    int n = (int)a.size(), best = 0;
    for (int k = n; k >= 1; --k) {
        bool ok = false;
        for (int mask = 0; mask < (1 << n) && !ok; ++mask) {
            if (__builtin_popcount((unsigned)mask) != k) continue;
            vector<long long> v;
            for (int i = 0; i < n; ++i) if (mask & (1 << i)) v.push_back(a[i]);
            sort(v.begin(), v.end());
            bool good = true;
            for (int i = 0; i < k; ++i) if (v[i] < i + 1) { good = false; break; }
            if (good) ok = true;
        }
        if (ok) { best = k; break; }
    }
    return best;
}
static bool check(const string& exe, const vector<long long>& a, int id) {
    const string inF = "l4a03p2_in.txt", outF = "l4a03p2_out.txt";
    {
        ofstream o(inF);
        o << a.size() << '\n';
        for (size_t i = 0; i < a.size(); ++i) o << a[i] << (i + 1 == a.size() ? '\n' : ' ');
    }
    int code = system(("\"" + exe + "\" < " + inF + " > " + outF + " 2>/dev/null").c_str());
    ifstream in(outF);
    long long got = -1;
    in >> got;
    int want = (int)a.size() <= 10 ? brute(a) : greedy(a);
    if (code != 0 || got != want) {
        cout << "[FAIL] case " << id << ": expected=" << want
             << ", actual=" << got << ", status=" << code << '\n';
        return false;
    }
    return true;
}
int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    const string exe = argv[1];
    int passed = 0, total = 0;
    vector<long long> c1 = {3, 1, 4, 1};
    ++total; if (check(exe, c1, 1)) ++passed;  // 样例1
    vector<vector<long long>> small;
    small.push_back(vector<long long>{1});
    small.push_back(vector<long long>{100});
    small.push_back(vector<long long>{1, 1, 1});
    small.push_back(vector<long long>{2, 1, 1});
    small.push_back(vector<long long>{1, 3});
    small.push_back(vector<long long>{2, 2});
    small.push_back(vector<long long>{1, 2, 1});
    small.push_back(vector<long long>{5, 1, 1, 1});
    for (size_t i = 0; i < small.size(); ++i) {
        ++total; if (check(exe, small[i], 2 + i)) ++passed;
    }
    {
        vector<long long> all1(1000, 1);
        ++total; if (check(exe, all1, 10)) ++passed;
        vector<long long> inc(1000);
        for (int i = 0; i < 1000; ++i) inc[i] = i + 1;
        ++total; if (check(exe, inc, 11)) ++passed;
    }
    srand(20240302);
    for (int t = 0; t < 5; ++t) {
        int n = 1 + rand() % 9;
        vector<long long> c(n);
        for (int i = 0; i < n; ++i) c[i] = 1 + rand() % 12;
        ++total; if (check(exe, c, 12 + t)) ++passed;
    }
    for (int t = 0; t < 3; ++t) {
        int n = 10000 + rand() % 190000;
        vector<long long> c(n);
        for (int i = 0; i < n; ++i) c[i] = 1 + rand() % 1000000000L;
        ++total; if (check(exe, c, 17 + t)) ++passed;
    }
    cout << "Results: " << passed << "/" << total << " passed" << '\n';
    return passed == total ? 0 : 1;
}
